    # Complete cyclic diagonals in whichever diagonal direction the
    # nonzero clues consistently follow.
    for sign in (1, -1):
        groups = {}
        for r in range(h):
            for c in range(w):
                v = grid[r][c]
                if v:
                    key = (c - sign * r) % w
                    groups.setdefault(key, []).append(v)
        if groups and all(len(set(vals)) == 1 for vals in groups.values()):
            colors = {k: vals[0] for k, vals in groups.items()}
            if len(colors) == w:
                return [[colors[(c - sign * r) % w] for c in range(w)]
                        for r in range(h)]

    # Repeat the observed sequence of nonblank horizontal stripes,
    # preserving their row spacing and extending periodically.
    known = [(r, row[:]) for r, row in enumerate(grid) if any(row)]
    if not known:
        return [row[:] for row in grid]

    # The stripe sequence's period is the distance between repeated
    # stripe colors/rows, or the span of the observed stripes.
    period = known[-1][0] - known[0][0]
    if period == 0:
        period = 1
    result = []
    for r in range(h):
        match = next((row for rr, row in known if (rr - r) % period == 0), None)
        result.append(match[:] if match is not None else grid[r][:])
    return result
